public static int findNthLeapYear(int Y, int N) {
    while (N > 0) {
        if (isLeapYear(Y)) {
            N--;
        }
        Y++; // Increment Y to the next year
    }
    if (isLeapYear(Y)) {
        N--; // Correct for looping back to a leap year
    }
    return Y; // Return the Nth leap year
}

