public static int maxRegions(int N) {
    if (N < 0) {
        throw new IllegalArgumentException("Invalid input: N must be a non-negative integer");
    }
    if (N == 0) {
        return 1;
    }

    int regions = N + 1;

    // Apply the formula for the maximum regions of a triangle mountain
    regions += (3 * N * (N + 1)) / 2;

    return regions;
}

public static int maxRegions(int N) {
    // If N is 0, it means the plane is already divided into 1 region
    if (N == 0) {
        return 1;
    }
    // For N greater than 0, the formula to calculate the maximum number of regions is (N + 2)^2 - 1
    return (N + 2) * (N + 2) - 1;
}

