public static String appx(String word1, String word2) {
    // Validate input strings
    if (word1 == null || word2 == null || word1.isEmpty() || word2.isEmpty()) {
        throw new IllegalArgumentException("Both words must be non-null and non-empty.");
    }

    // Calculate the length of the combined prefix
    int prefixLength = 0;
    int i = 0;

    while (i < word1.length() && i < word2.length() && word1.charAt(i) == word2.charAt(i)) {
        prefixLength++;
        i++;
    }

    // Calculate the length of the combined suffix
    int suffixLength = 0;
    int j = word1.length() - 1;
    int k = word2.length() - 1;

    while (j >= 0 && k >= 0 && word1.charAt(j) == word2.charAt(k)) {
        suffixLength++;
        j--;
        k--;
    }

    // Calculate the length of the common letters
    int commonLength = suffixLength - prefixLength;

    // Calculate the approximate value as a reduced fraction
    int numerator = commonLength;
    int denominator = word1.length() + word2.length() - 2 * prefixLength;

    // Simplify the fraction
    if (denominator % numerator == 0) {
        denominator /= numerator;
        numerator = 1;
    }

    // Return the simplified fraction as a string
    return "appx(" + word1 + ", " + word2 + ") = " + numerator + "/" + denominator;
}

public static String appx(String word1, String word2) {
    // Count the common letters and calculate the sum of the lengths
    int commonLetters = 0;
    for (char ch1 : word1.toCharArray()) {
        for (char ch2 : word2.toCharArray()) {
            if (ch1 == ch2) {
                commonLetters++;
                break;
            }
        }
    }

    int length1 = word1.length();
    int length2 = word2.length();

    // Calculate the greatest common divisor (GCD)
    int gcd = ((length1 > length2) ? length1 : length2);
    while (gcd != 1) {
        if (length1 % gcd == 0 && length2 % gcd == 0) {
            break;
        }
        gcd--;
    }

    // Calculate the reduced fraction
    int simplifiedCommon = commonLetters / gcd;
    int totalLength = length1 + length2;
    int simplifiedTotal = totalLength / gcd;

    return "appx(" + word1 + ", " + word2 + ") = " + simplifiedCommon + "/" + simplifiedTotal;
}

public static String appx(String word1, String word2) {
    if (word1 == null || word2 == null || word1.isEmpty() || word2.isEmpty() || word1.length() != word2.length()) {
        throw new IllegalArgumentException("Both words must be non-empty and of the same length.");
    }

    int commonLetters = 0;
    int sumOfLengths = word1.length() * word2.length();

    for (int i = 0; i < word1.length(); i++) {
        if (word1.charAt(i) == word2.charAt(i)) {
            commonLetters++;
        }
    }

    if (commonLetters == 0) {
        return "0";
    } else {
        Rational fraction = new Rational(commonLetters, sumOfLengths);
        return fraction.toString();
    }
}

