public boolean canArrange(int[] arr, int k) {
    // Check if the total sum of the array is not divisible by k
    if ((arr.length * (arr.length + 1) / 2) % k != 0) {
        return false;
    }

    // Count the remainders of the array elements when divided by k
    int[] remainderCount = new int[k];

    for (int num : arr) {
        remainderCount[num % k]++;
    }

    // Check if the count of remainders 0, 1, and k-1 are both even or both odd
    if ((remainderCount[0] % 2 == 0 && remainderCount[k / 2] % 2 == 0) ||
        (remainderCount[0] % 2 != 0 && remainderCount[k / 2] % 2 != 0)) {
        return true;
    }

    return false;
}

public boolean canArrange(int[] arr, int k) {
    // Edge case: if arr length is odd, it's impossible to pair up
    if (arr.length % 2 != 0) return false;

    // Use a HashMap to count remainders of each element when divided by k
    Map<Integer, Integer> remainderCount = new HashMap<>();
    for (int num : arr) {
        int remainder = num % k;
        remainderCount.put(remainder, remainderCount.getOrDefault(remainder, 0) + 1);
    }

    // Check if the counts of remainders that sum up to k are even
    for (int remainder : remainderCount.keySet()) {
        int complement = k - remainder;
        if (complement != remainder) {
            if (!remainderCount.containsKey(complement) || remainderCount.get(complement) % 2 != 0) {
                return false;
            }
        } else {
            // Special case: ifremainder is zero, it's possible to pair up all elements
            if (remainder == 0 && remainderCount.get(remainder) % 2 != 0) {
                return false;
            }
        }
    }

    // Otherwise, it's possible to pair up all elements
    return true;
}

public boolean canArrange(int[] arr, int k) {
    // Handle edge case for k being 0
    if (k == 0) {
        for (int num : arr) {
            if (num != 0) {
                return false;
            }
        }
        return true;
    }

    // Create a frequency map to count remainders when divided by k
    Map<Integer, Integer> remainderCount = new HashMap<>();
    for (int num : arr) {
        int remainder = num % k;
        remainderCount.put(remainder, remainderCount.getOrDefault(remainder, 0) + 1);
    }

    // Handle odd numbers
    if (remainderCount.containsKey(0)) {
        if remainderCount.get(0) % 2 != 0) {
            return false;
        }
    }

    // Handle pairs with same remainder
    for (int i = 1; i < k; i++) {
        if (remainderCount.containsValue(i) && remainderCount.containsValue(k - i)) {
            if (remainderCount.get(i) != remainderCount.get(k - i)) {
                return false;
            }
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    // Edge case: if the array length is odd, it's impossible to pair evenly
    if (arr.length % 2 != 0) {
        return false;
    }

    // Use a HashMap to store the remainder of each element when divided by k
    Map<Integer, Integer> remainderMap = new HashMap<>();
    for (int num : arr) {
        int remainder = num % k;
        if (remainderMap.containsKey(remainder)) {
            remainderMap.put(remainder, remainderMap.get(remainder) + 1);
        } else {
            remainderMap.put(remainder, 1);
        }
    }

    for (int i = 1; i < k / 2 + 1; i++) {
        // Check if the current remainder and its pair remainder are both present in the map
        if (!remainderMap.containsKey(k - i) || remainderMap.get(k - i) != remainderMap.get(i)) {
            return false;
        }
    }

    return true;
}

public boolean canArrange(int[] arr, int k) {
    // Edge case: if n is odd, it's impossible to divide into equal pairs
    if (arr.length % 2 != 0) return false;

    // Create a count map for remainders when divided by k
    Map<Integer, Integer> remainderCount = new HashMap<>();
    for (int num : arr) {
        int remainder = num % k;
        if (remainder == 0) {
            // If there are any odd counts of remainder 0, they need to be paired
            if (remainderCount.getOrDefault(0, 0) % 2 != 0) return false;
        } else {
            // Increment the count for the remainder
            remainderCount.put(remainder, remainderCount.getOrDefault(remainder, 0) + 1);
        }
    }

    // Check the remaining counts
    for (int remainder : remainderCount.keySet()) {
        if (remainder != 0 && remainderCount.get(remainder) != remainderCount.get(k - remainder)) {
            return false;
        }
    }

    return true;
}

