            this.hasApple = hasApple;
            this.time = 6; // default time is 6 seconds for collecting apples
        }
    }

    Queue<T> q = new LinkedList<>();
    q.add(new T(hasApple[0]));

    while (!q.isEmpty()) {
        T node = q.poll();
        int idx = node.hasApple ? 1 : 0; // if has apple, increase index by 1
        int current = 1; // current time is 1 second

        for (int neighbor : graph.getOrDefault(node.idx, new ArrayList<>())) {
            if (!q.isEmpty() && neighbor == q.peek().idx) {
                T neighborNode = q.poll();
                current += neighborNode.time; // move to heavier tree by adding height of shorter tree
