        adjacencyList.add(new ArrayList<>());
    }
    for (int[] edge : edges) {
        adjacencyList.get(edge[0]).add(edge[1]);
        adjacencyList.get(edge[1]).add(edge[0]);
    }

    // Helper function to perform DFS and return the total time taken
    int totalTime = dfs(0, adjacencyList, hasApple);

    // Subtract 1 from totalTime since we need to return to node 0 after collecting apples
    return totalTime - 1;
}

public int minTime(int n, int[][] edges, boolean[] hasApple) {
    // handle base cases
    if (n <= 1 || edges == null || hasApple == null) return 0;

    // initialize parent and time arrays
    int time = 0;
    int parent[] = new int[n];
    Arrays.fill(parent, -1);
    parent[0] = -2; // initialize parent of node 0

    // build adjacency list representation of the tree
    Map<Integer, List<Integer>> graph = new HashMap<>();
    for (int[] edge : edges) {
        graph.computeIfAbsent(edge[0], k -> new ArrayList<>()).add(edge[1]);
        graph.computeIfAbsent(edge[1], k -> new ArrayList<>()).add(edge[0]);
    }

    // perform DFS to calculate the minimum time required to collect all apples and return to node 0
    dfs(parent, 0, hasApple, time, graph);

    return time;
}

public String sortString(String s) {
