public String sortString(String s) {
    if (s == null || s.isEmpty()) return "";

    char[] chars = s.toCharArray();
    Arrays.sort(chars);
    String result = "";
    int i = 0, j = chars.length - 1;
    while (i <= j) {
        if (i == j) {
            result += String.valueOf(chars[i]);
            i++;
        } else {
            result += String.valueOf(chars[i]) + String.valueOf(chars[j]);
            i++;
            j--;
        }
    }
    return result;
}

public String sortString(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }

    List<Character> asciiChars = new ArrayList<>();
    for (char c : s.toCharArray()) {
        asciiChars.add(c);
    }

    asciiChars.sort(Comparator.comparingInt(Character::codePointAt));

    StringBuilder sortedString = new StringBuilder();

    // Sort字符串
    while (!asciiChars.isEmpty()) {
        // Pick and add the smallest character not yet added
        int smallestIndex = findSmallestIndex(asciiChars);
        if (smallestIndex != -1) {
            sortedString.append(asciiChars.remove(smallestIndex));
        }

        // Pick and add the largest character not yet added
        int largestIndex = findLargestIndex(asciiChars);
        if (largestIndex != -1) {
            sortedString.append(asciiChars.remove(largestIndex));
        }
    }

    return sortedString.toString();
}

public String sortString(String s) {
    if (s == null || s.length() == 0) {
        return "";
    }

    char[] chars = s.toCharArray();
    Arrays.sort(chars);

    StringBuilder result = new StringBuilder();
    int left = 0;
    int right = chars.length - 1;

    while (left <= right) {
        if (left == right) {
            result.append(chars[left]);
        } else {
            result.append(chars[left++]);
            result.append(chars[right--]);
        }
    }

    return result.toString();
}

public String sortString(String s) {
    map<Character, List<Character>> charMap = new HashMap<>();
    for (char c : s.toCharArray()) {
        charMap.putIfAbsent(c, new ArrayList<>());
        charMap.get(c).add(c);
    }

    StringBuilder result = new StringBuilder();
    for (int i = 0; i < s.length(); i++) {
        PriorityQueue<Character> pq = new PriorityQueue<>();
        for (char key : charMap.keySet()) {
            if (!charMap.get(key).isEmpty()) {
                pq.offer(key);
            }
        }

        if (pq.isEmpty()) {
            break;
        }

        while (pq.isEmpty() || (pq.peek() == result.charAt(result.length() - 1) && charMap.get(pq.poll()).isEmpty())) {
            pq.offer(pq.peek());
        }

        Collection<Character> lastElements = charMap.get(pq.poll());
        if (!lastElements.isEmpty()) {
            Collections.sort(lastElements);
            for (char c : lastElements) {
                result.append(c);
                charMap.put(c, charMap.get(c).subList(1, charMap.get(c).size()));
            }
        }
    }

    return result.toString();
}

