    }

    // If total sum is odd, it cannot be split into two equal averages
    if (totalSum % 2 != 0) return false;

    // Calculate the target sum for each subarray to achieve average
    double targetSum = totalSum / 2;

    // Sort the array to use two-pointer technique
    Arrays.sort(nums);

    // Initialize two pointers at the start and end of the array
    int left = 0;
    int right = length - 1;

    // Use two-pointer technique to check for equal average subset
    while (left < right) {
        double sum = (nums[left] + nums[right]) / 2.0;

        // If sum matches the target sum, check for valid subarrays
        if (sum == targetSum) {
            // Check if both subarrays are non-empty
            if (left + 1 < length && right - 1 >= 0) {
                return true;
            }
            // Check if there is a valid non-empty portion on the left side
            while (left + 1 < length && nums[left] == nums[left + 1]){
                left++;
            }
            // Check if there is a valid non-empty portion on the right side
            while (right - 1 >= 0 && nums[right] == nums[right - 1]){
                right--;
            }
        }

        // Move left pointer right if sum is less than target sum
        if (sum < targetSum) {
            left++;
        }
