        throw new IllegalArgumentException("Input array cannot be null or empty.");
    }

    int n = cost.length;
    int[] dp = new int[n];

    if (n == 1) {
        return cost[0];
    }

    dp[0] = cost[0];
    dp[1] = Math.min(cost[0], cost[1]);

    for (int i = 2; i < n; i++) {
        dp[i] = Math.min(dp[i - 2] + cost[i], dp[i - 1] + cost[i]);
    }

    return dp[n - 1];
}

