public int minCostClimbingStairs(int[] cost) {
    if (cost == null || cost.length <= 2) {
        return cost != null ? cost[0] : 0;
    }

    int prev1 = cost[0];
    int prev2 = cost[1];
    int current = prev1 + prev2;

    for (int i = 2; i < cost.length; i++) {
        int temp = current;
        current = Math.min(prev1 + cost[i], prev2 + cost[i]);
        prev1 = prev2;
        prev2 = temp;
    }

    return current;
}

