public boolean hasAllCodes(String s, int k) {
    int n = s.length();
    int m = n - k + 1;
    Map<String, Integer> seen = new HashMap<>();
    if (m < k) return false; // Not enough substrings to cover all combinations

    for (int i = 0; i < m; i++) {
        String sub = s.substring(i, i + k);
        seen.put(sub, seen.getOrDefault(sub, 0) + 1);
        if (seen.get(sub) > 1) return false; // Duplicate substring found
    }

    return true;
}

public boolean hasAllCodes(String s, int k) {
        int n = s.length();
        int requiredSize = (1 << k);
        Set<String> seen = new HashSet<>();

        // Check all possible bit patterns of length k
        for (int i = 0; i <= n - k; i++) {
            String bitPattern = s.substring(i, i + k);
            if (!seen.add(bitPattern)) {
                // Duplicate found, string cannot be composed
                return false;
            }
        }

        // If all bit patterns were found, check required bit size
        return seen.size() == requiredSize;
    }

public static boolean hasAllCodes(String s, int k) {
        if (s == null || k <= 0) {
            throw new IllegalArgumentException("Invalid input");
        }

        int totalCodes = 1 << k;
        HashSet<String> seen = new HashSet<>();
        for (int i = 0; i <= s.length() - k; i++) {
            String code = s.substring(i, i + k);
            if (!seen.contains(code)) {
                seen.add(code);
                if (seen.size() == totalCodes) {
                    return true;
                }
            }
        }
        return false;
    }

public boolean hasAllCodes(String s, int k) {
    int totalCodes = (int) Math.pow(2, k);
    boolean[] seen = new boolean[totalCodes];

    int left = 0;
    int count = 0;

    for (int right = 0; right < s.length(); right++) {
        int mask = (1 << (k - 1)) - 1; // Mask the current character indices
        int code = (s.charAt(right) - '0') << (k - 1); // Left shift the mask
        if ((code & mask) == 0) {
            // Unmask the current character
            code = code >> (k - 1);
            if (seen[code]) {
                // If the code is already seen, return false
                return false;
            }
            seen[code] = true;
            count++;
        }

        // Remove the leftmost character of the current window
        if (right - left + 1 > k) {
            mask = (1 << (k - 1)) - 1; // Update the mask
            code = (s.charAt(left) - '0') << (k - 1); // Left shift the mask
            if ((code & mask) == 0) {
                // Remove the leftmost character of the current window
                code = code >> (k - 1);
                if (seen[code]) {
                    // If the code is already seen, return false
                    return false;
                }
                seen[code] = true;
                count--;
            }
            left++;
        }
    }

    return count == totalCodes;
}

