public int findMinFibonacciNumbers(int k) {
    TreeSet<Integer> fibSet = new TreeSet<>();
    fibSet.add(1);
    fibSet.add(2);
    int fib1 = 1, fib2 = 2;
    while (fib1 + fib2 <= k) {
        fibSet.add(fib1);
        fib1 = fib1 + fib2;
    }

    LinkedList<Integer> result = new LinkedList<>();
    int current = k;
    while (current > 0) {
        if (fibSet.contains(current)) {
            result.addFirst(current);
            current -= current;
        } else {
            int previousFib1 = fibSet.floor(fib1);
            int previousFib2 = fibSet.floor(fib2) - current;
