        char[] chars = s.toCharArray();
        for (int j = 0; j < i; j++) {
            left.add(chars[j]);
        }
        possibleSubstrings.add(left);

        List<Character> right = new ArrayList<>();
        for (int j = i + 1; j < n; j++) {
            right.add(chars[j]);
        }
        possibleSubstrings.add(right);
    }

    // Add the incomplete string(s) as is
    if (n >= 3) {
        possibleSubstrings.add(new ArrayList<>(Arrays.asList(s.charAt(0), s.charAt(1), s.charAt(2))));
    }

    // We want to have the maximum number of unique substrings, so we need to remove any duplicates
    HashSet<ArrayList<Character>> distinctSubstrings = new HashSet<>();
    for (List<Character> substring : possibleSubstrings) {
        distinctSubstrings.add(new ArrayList<>(substring));
    }

    // Return the size of the distinct substrings
    return distinctSubstrings.size();
}

