public static boolean isPowerOfTwo(int n) {
    // Negative numbers, 0, and numbers less than 2 are not powers of two
    if (n <= 0 || n < 2) {
        return false;
    }
    // If n is a power of two, it must have exactly one bit set to 1
    // The bitwise AND of a number with one less than itself should be zero
    return (n & (n - 1)) == 0;
}

