public static int longestLine(int[][] mat) {
    if (mat == null || mat.length == 0 || mat[0].length == 0) return 0;

    int rows = mat.length, cols = mat[0].length;
    int[][] up = new int[rows][cols];
    int[][] down = new int[rows][cols];
    int[][] left = new int[rows][cols];
    int[][] right = new int[rows][cols];
    int[][] diagonal = new int[rows][cols];
    int[][] antiDiagonal = new int[rows][cols];

    int maxLength = 0;
    for (int i = 0; i < rows; i++) {
        for (int j = 0; j < cols; j++) {
            if (mat[i][j] == 1) {
                // Top
                if (i - 1 >= 0 && mat[i - 1][j] == 1) up[i][j] = up[i - 1][j] + 1;
                else up[i][j] = 1;

                // Bottom
                if (i + 1 < rows && mat[i + 1][j] == 1) down[i][j] = down[i + 1][j] + 1;
                else down[i][j] = 1;

                // Left
                if (j - 1 >= 0 && mat[i][j - 1] == 1) left[i][j] = left[i][j - 1] + 1;
                else left[i][j] = 1;

                // Right
                if (j + 1 < cols && mat[i][j + 1] == 1) right[i][j] = right[i][j + 1] + 1;
                else right[i][j] = 1;

                // Diagonal
                if (i - 1 >= 0 && j - 1 >= 0 && mat[i - 1][j - 1] == 1) diagonal[i][j] = diagonal[i - 1][j - 1] + 1;
                else diagonal[i][j] = 1;

                // Anti-diagonal
                if (i - 1 >= 0 && j + 1 < cols && mat[i - 1][j + 1] == 1) antiDiagonal[i][j] = antiDiagonal[i - 1][j + 1] + 1;
                else antiDiagonal[i][j] = 1;

                maxLength = Math.max(maxLength, up[i][j]);
                maxLength = Math.max(maxLength, down[i][j]);
                maxLength = Math.max(maxLength, left[i][j]);
                maxLength = Math.max(maxLength, right[i][j]);
                maxLength = Math.max(maxLength, diagonal[i][j]);
                maxLength = Math.max(maxLength, antiDiagonal[i][j]);
            }
        }
    }

    return maxLength;
}

public static String addThousandSeparator(int n) {
    // This function takes an integer and returns a string with thousand separators added
    // Example:
    // addThousandSeparator(987) returns "987"
    // addThousandSeparator(1234) returns "1.234"
    // addThousandSeparator(123456789) returns "123.456.789"
    // addThousandSeparator(0) returns "0"

    if (n == 0) {
        return "0";
    }

    // Convert the integer to a string
    String numStr = Integer.toString(n);
    StringBuilder result = new StringBuilder();

    // Process the string from right to left
    for (int i = numStr.length() - 1; i >= 0; i--) {
        if (i > 0 && ((numStr.length() - i) % 3 == 0)) {
            result.append(".");
        }
        result.append(numStr.charAt(i));
    }

    // Reverse the result to get the correct order
    return result.reverse().toString();
}

public static String addThousandSeparator(int n) {
    if (n == 0) return "0";

    StringBuilder result = new StringBuilder();
    String numStr = Integer.toString(n);
    int i = 0;

    while (i < numStr.length()) {
        int lengthToAdd = Math.min(3, numStr.length() - i);
        result.insert(0, numStr.substring(i, i + lengthToAdd));
        i += lengthToAdd;
        if (i < numStr.length()) result.insert(0, ".");
    }

    return result.toString();
}

