    if (n == 0) {
        return "0";
    }
    StringBuilder result = new StringBuilder(String.valueOf(n));
    int length = result.length();
    int separatorPosition = 3;
    while (length > separatorPosition) {
        result.insert(length - separatorPosition, ".");
        length += 3;
        separatorPosition += 3;
    }
    return result.toString();
}

