                    col++;
                } else {
                    row--;
                }
            }
        } else {
            row = nextRow;
            col = nextCol;
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    int rows = mat.length;
    int cols = mat[0].length;
    int[] result = new int[rows * cols]; // Total number of elements in the matrix

    int r = 0, c = 0, dir = 0; // Initial row, column, and direction
    while (r < rows && c < cols) {
        result[dir + r * cols] = mat[r][c]; // Store the current element

        if (dir == 0) { // Moving from top-left to bottom-right
            if (c == cols - 1) { // Move to the next row
                dir = 1;
                r++;
            } else { // Move to the right
                c++;
            }
        } else if (dir == 1) { // Moving from top-right to bottom-left
            if (r == rows - 1) { // Move to the next column
                dir = 2;
                c++;
            } else { // Move down
                r++;
            }
        } else if (dir == 2) { // Moving from bottom-right to top-left
            if (c == 0) { // Move to the previous row
                dir = 3;
                r--;
            } else { // Move left
                c--;
            }
        } else if (dir == 3) { // Moving from bottom-left to top-right
            if (r == 0) { // Move to the previous column
                dir = 0;
                c++;
            } else { // Move up
                r--;
            }
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
    int m = mat.length, n = mat[0].length;
    int[] result = new int[m * n];
    boolean rowChange = true;

    int curRow = 0, curCol = 0;
    int count = 0;

    while (count < m * n) {
        result[count++] = mat[curRow][curCol];

        if (rowChange) {
            if (curRow + 1 < m && curCol == 0) {
                rowChange = false;
                curRow++;
            } else if (curRow + 1 < m && curCol + 1 < n) {
                curRow++;
                curCol++;
            } else {
                rowChange = false;
                curCol++;
            }
        } else {
            if (curRow == 0 && curCol + 1 < n) {
                rowChange = true;
                curCol++;
            } else if (curRow - 1 >= 0 && curCol + 1 < n) {
                curRow--;
                curCol++;
            } else {
                rowChange = true;
                curRow--;
            }
        }
    }

    return result;
}

public static int[] diagonalOrder(int[][] mat) {
