    int[] result = new int[rows * cols];
    int row = 0, col = 0, dir = 1; // 'dir' indicates the current diagonal direction

    for (int i = 0; i < rows * cols; i++) {
        result[i] = mat[row][col];
        if (dir == 1) {
            // Move right if possible, otherwise down
            if (col < cols - 1) {
                col++;
            } else {
                row++;
                dir = -1;
            }
        } else {
            // Move down if possible, otherwise left
            if (row < rows - 1) {
                row++;
            } else {
                col++;
                dir = 1;
            }
        }
    }

    return result;
}

public static int findSmallestInteger(int n) {
    // Convert the integer to an array of digits
    int[] digits = new int[String.valueOf(n).length()];
    for (int i = 0; i < digits.length; i++) {
        digits[i] = n % 10;
        n /= 10;
    }

    // Start from the largest possible prefix and check if it can be sorted
    for (int i = digits.length - 1; i > 0; i--) {
        if (digits[i] > digits[i - 1]) {
            // Find the smallest element in the suffix that is greater than the pivot
            for (int j = digits.length - 1; j > i - 1; j--) {
                if (digits[j] > digits[i - 1]) {
                    // Swap the pivot with the smallest element in the suffix
                    int temp = digits[i - 1];
                    digits[i - 1] = digits[j];
                    digits[j] = temp;
                    break; // No need to continue searching since the rest of the digits are in descending order
                }
            }

            // Sort the suffix in ascending order
            Arrays.sort(digits, i, digits.length);

            // Form the smallest integer from the digits
            int result = 0;
            for (int d : digits) {
                result = result * 10 + d;
            }

            return result;
        }
    }

    // If no valid permutation is found, return -1
    return -1;
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    String numStr = String.valueOf(n);
    int len = numStr.length();

    // Check if all digits are the same
    boolean allSame = true;
    for (int i = 1; i < len; i++) {
        if (numStr.charAt(i) != numStr.charAt(0)) {
            allSame = false;
            break;
        }
    }

    if (allSame) {
        return -1;
    }

    // Find the index where the digit needs to be swapped
    StringBuilder smallestNumStr = new StringBuilder(numStr);
    for (int i = 0; i < len - 1; i++) {
        if (numStr.charAt(i) > numStr.charAt(i + 1)) {
            // Find the smallest digit that is greater than numStr.charAt(i)
            char smallestDigit = '9';
            for (int j = i + 1; j < len; j++) {
                if (numStr.charAt(j) < smallestDigit && numStr.charAt(j) > numStr.charAt(i)) {
                    smallestDigit = numStr.charAt(j);
                }
            }

            // Swap numStr.charAt(i) and smallestDigit
            char temp = smallestNumStr.charAt(i);
            smallestNumStr.setCharAt(i, smallestNumStr.charAt(j));
            smallestNumStr.setCharAt(j, temp);

            // Construct the smallest possible number
            int smallestNum = Integer.parseInt(smallestNumStr.toString());

            // Check if the smallest number is greater than n
            return smallestNum > n ? smallestNum : -1;
        }
    }

    return -1; // Should not reach here if all digits are the same and n is positive
}

public static int findSmallestInteger(int n) {
    if (n < 10) {
        return -1;
    }

    int[] digits = new int[10];
    int temp = n;
    while (temp > 0) {
        digits[temp % 10]++;
        temp /= 10;
    }

    for (int i = 9; i >= 0; i--) {
        while (digits[i] > 0) {
            digits[i]--;
            int candidate = n * 10 + i;
            if (candidate > n && candidate != n) {
                return candidate;
            }
        }
    }

    return -1;
}

public static int findSmallestInteger(int n) {
    if (n <= 9) return -1; // Single-digit numbers cannot be rearranged greater than themselves

    char[] digits = String.valueOf(n).toCharArray();
    Arrays.sort(digits);

    for (int i = digits.length - 2; i >= 0; i--) {
        if (digits[i] < digits[i + 1]) {
            for (int j = i + 1; j < digits.length; j++) {
                if (digits[j] > digits[i]) {
                    // Swap the digits
                    char temp = digits[i];
                    digits[i] = digits[j];
                    digits[j] = temp;

                    // Sort the remaining digits
                    Arrays.sort(digits, i + 1, digits.length);

                    // Convert back to integer
                    return Integer.parseInt(new String(digits));
                }
            }
        }
    }

    return -1; // No valid rearrangement found
}

public static int findSmallestInteger(int n) {
    if (n <= 0) {
        throw new IllegalArgumentException("Input must be a positive integer.");
    }

    char[] digits = String.valueOf(n).toCharArray();
    int maxIndex = digits.length - 1;

    // Find the first digit from the end that is smaller than its predecessor.
    while (maxIndex > 0 && digits[maxIndex - 1] >= digits[maxIndex]) {
        maxIndex--;
    }

    if (maxIndex == 0) {
        // If no such digit exists, return -1.
        return -1;
    }

    // Find the smallest digit from the end that is greater than the identified digit.
    int minIndex = digits.length - 1;
    while (digits[minIndex] <= digits[maxIndex]) {
        minIndex--;
    }

    // Swap the identified digits.
    char temp = digits[maxIndex];
    digits[maxIndex] = digits[minIndex];
    digits[minIndex] = temp;

    // Sort the digits from the end to the identified index.
    Arrays.sort(digits, maxIndex + 1, digits.length);

    // Convert the modified digits back to an integer.
    return Integer.parseInt(new String(digits));
}

