    }

    // Calculate the vectors between the points
    int[][] vectors = new int[2][2];
    vectors[0] = new int[]{points[1][0] - points[0][0], points[1][1] - points[0][1]};
    vectors[1] = new int[]{points[2][0] - points[0][0], points[2][1] - points[0][1]};

    // Check if the vectors are not collinear (not parallel)
    if (vectors[0][0] * vectors[1][1] != vectors[1][0] * vectors[0][1]) {
        return true;
    }

    return false;
}

public static boolean isBoomerang(int[][] points) {
        int n = points.length;
        // Edge case: check if there are less than 3 points
        if (n < 3) {
            return false;
        }
        // Calculate the area of the triangle formed by the three points
        int area = 0;
        for (int i = 0; i < n; i++) {
            int j = (i + 1) % n;
            area += points[i][0] * points[j][1];
            area -= points[i][1] * points[j][0];
        }
        // If the area is zero, the points do not form a triangle
        // If the area is non-zero, the points do form a triangle
        return area != 0;
    }

public boolean isBoomerang(int[][] points) {
    if (points == null || points.length < 3) {
        throw new IllegalArgumentException("Input points array must contain at least 3 points");
    }

    int x1 = points[0][0], y1 = points[0][1];
    int x2 = points[1][0], y2 = points[1][1];
    int x3 = points[2][0], y3 = points[2][1];

    // Check for collinearity
    if (x1 * (y2 - y3) + x2 * (y3 - y1) + x3 * (y1 - y2) == 0) {
        return false;
    }

    // Check for perpendicularity (slopes being reciprocal)
    if ((y2 - y3) * (x3 - x1) == 0) {
        return false;
    }

    return true;
}

