    int dy1 = points[1][1] - points[0][1];
    int dx2 = points[2][0] - points[0][0];
    int dy2 = points[2][1] - points[0][1];

    // Calculate the determinants of the matrices formed by the points
    int det1 = dx1 * dy2 - dy1 * dx2;

    // Check if the determinant is non-zero, which means the points do not form a collinear line
    return det1 != 0;
}

