public static int minPerfectSquareSum(int n) {
        if (n < 1) {
            throw new IllegalArgumentException("Input must be a positive integer.");
        }

        int dp[] = new int[n + 1];
       Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0; // Base case: 0 perfect squares sum up to 0

        // Iterate through each number from 1 to n
        for (int i = 1; i <= n; i++) {
            // Check all possible perfect squares less than i
            for (int j = 1; j * j <= i; j++) {
                int sum = j * j;
                dp[i] = Math.min(dp[i], dp[i - sum] + 1);
            }
        }

        return dp[n];
    }

public static String reverseWords(String s) {
    // Handle empty or null input
    if (s == null) {
        return null;
    }

    // Split the string into words
    String[] words = s.split(" ");

    // Reverse each word
    for (int i = 0; i < words.length; ++i) {
        words[i] = new StringBuilder(words[i]).reverse().toString();
    }

    // Join the reversed words back into a string
    return String.join(" ", words);
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        return "";
    }

    String[] words = s.split(" ");
    String reversedString = "";

    for (String word : words) {
        if (!word.isEmpty()) {
            StringBuilder reversedWord = new StringBuilder(word).reverse();
            reversedString += reversedWord.toString() + " ";
        }
    }

    return reversedString.trim();
}

public static String reverseWords(String s) {
    if (s == null || s.isEmpty()) {
        throw new IllegalArgumentException("Input string cannot be null or empty");
    }

    String[] words = s.split("\\s+");
    StringBuilder reversedString = new StringBuilder();
    for (String word : words) {
        StringBuilder reversedWord = new StringBuilder();
        for (int i = word.length() - 1; i >= 0; i--) {
            reversedWord.append(word.charAt(i));
        }
        reversedString.append(reversedWord.toString()).append(" ");
    }

    // Remove the trailing space
    return reversedString.toString().trim();
}

public static String reverseWords(String s){
    String[] words = s.split(" ");
    StringBuilder result = new StringBuilder();
    for(String word : words){
        result.append(new StringBuilder(word).reverse().toString());
        result.append(" ");
    }
    // Remove the trailing space
    return result.toString().trim();
}

public static String reverseWords(String s) {
    // Split the input string into words based on spaces
    String[] words = s.split(" ");
    // Use StringBuilder for efficient string manipulation
    StringBuilder result = new StringBuilder();

    // Reverse each word and append to the result
    for (String word : words) {
        result.append(reverse(word)).append(" ");
    }

    // Remove the trailing space and return the result
    return result.toString().trim();
}
